SELECT s0."id", s0."number", s0."__calculations__product_name", s0."__calculations__latest_payment_status", s0."__calculations__latest_payment_paid_at", s0."__order__" FROM (SELECT DISTINCT ON (si0."id", si0."id") si0."id" AS "id", si0."number" AS "number", sp1."name"::text AS "__calculations__product_name", ss2."status"::text AS "__calculations__latest_payment_status", ss2."paid_at"::timestamp AS "__calculations__latest_payment_paid_at", row_number() OVER "order" AS "__order__" FROM "invoices" AS si0 LEFT OUTER JOIN "public"."products" AS sp1 ON si0."product_id" = sp1."id" LEFT OUTER JOIN LATERAL (SELECT ssp0."status" AS "status", ssp0."paid_at" AS "paid_at" FROM "public"."payments" AS ssp0 WHERE (si0."id" = ssp0."invoice_id") ORDER BY ssp0."created_at" DESC, ssp0."id" DESC LIMIT 1) AS ss2 ON TRUE WINDOW "order" AS (ORDER BY si0."id") ORDER BY si0."id", si0."id") AS s0 ORDER BY s0."__order__"
